cess": {"is_oa": true, "oa_status": "green", "oa_url": "https://arxiv.org/pdf/2609.24755", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:arXiv.org:2609.24755", "doi": null, "is_oa": true, "landing_page_url": "https://arxiv.org/abs/2609.24755", "pdf_url": "https://arxiv.org/pdf/2609.24755", "source": {"id": "https://openalex.org/S4306400194", "display_name": "arXiv (Cornell University)", "issn_l": "2331-8422", "issn": ["2331-8422"], "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I205783295", "host_organization_name": "Cornell University", "host_organization_lineage": ["https://openalex.org/I205783295"], "host_organization_lineage_names": [], "type": "repository"}, "license": null, "license_id": null, "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "Autonomous AI agents are increasingly deployed in areas where wrong decisions are hard to reverse. This paper examines schema mismatch: the condition in which an agent operates within an interpretive frame that no longer applies to the current context. Outputs produced under such a mismatch can appear internally consistent, linguistically plausible, and largely factually correct; output-quality metrics alone therefore capture the underlying loss of validity only partially. The paper introduces Epi-Logic, a conceptual framework for epistemic runtime control. It couples the detection of schema dissonance, a graduated reduction of autonomy, and the auditable switch to a validated schema. A schema is formalised as a tuple of variable space, expectation model, validity conditions, axioms, and metadata. The Epi-Score aggregates seven graded dimensions of epistemic dissonance; the temporal validity dimension D8, violations of the validity conditions G, and axiom violations are carried as separate categorical paths that are not offset against the aggregate. The architecture rests on a checking asymmetry: formalised validity conditions can be checked at runtime, whereas the correctness of many actions is established only ex post. The paper separates two architectural properties, a conditional result from sequential changepoint detection, and an empirical remainder. Eight falsifiable propositions with named baselines describe the transition to empirical validation. All propositions are empirically testable hypotheses, not established results."}]", "excerpt_truncated": true, "source_sha256": "5e6e319b20f4892145bebcb8e18e396e56b531d94ea13aee0864943f443dd80a", "verification_required": true, "topic_domain": "assumption_challenge", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["openalex:W7172081649", "arxiv:2609.24755"], "source_candidates": ["https://philsci-archive.pitt.edu/30629/1/AI_Regress_LeeSursinRyoo.pdf", "https://arxiv.org/pdf/2609.24755", "https://arxiv.org/abs/2609.24755"], "source_candidate_identities": {}}

